Each filter is a ``Filter`` subclass carrying its public registry ``name`` and
implementing ``apply(self, text)``.

Exact semantics (callers and tests rely on these -- keep them bit-identical
across refactors):
  * dedupe_words(text): split the text on runs of whitespace, drop repeated
    words keeping only each word's first occurrence (in order), and join the
    survivors with single spaces.
  * sort_words(text):   split the text on runs of whitespace, sort the words
    alphabetically (duplicates kept), and join them with single spaces.

Like the filters in ``text.py`` and ``spacing.py`` these classes carry
``@register``, so merely importing this module registers them for
``get_filter``.
"""
from ..base import Filter
from ..registry import register


@register
class DedupeWords(Filter):
    """dedupe_words: drop repeated words, keeping first occurrences."""

    name = "dedupe_words"

    def apply(self, text):
        seen = set()
        unique = []
        for word in text.split():
            if word not in seen:
                seen.add(word)
                unique.append(word)
        return " ".join(unique)


@register
class SortWords(Filter):
    """sort_words: sort the words alphabetically (duplicates kept)."""

    name = "sort_words"

    def apply(self, text):
        return " ".join(sorted(text.split()))
"}

